<script>
(function(){
  const monthNames=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
  const weekdayNames=['السبت','الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','جمعة'];

  let state = { year:new Date().getFullYear(), month:new Date().getMonth(), day:null, time:null };

  const grid = document.getElementById('cal-grid');
  const monthLabel = document.getElementById('month-label');
  const summary = document.getElementById('summary');
  const confirmBtn = document.getElementById('confirmBtn');
  const hint = document.getElementById('hint');

  function renderMonth(){
    const {year,month} = state;
    monthLabel.textContent = monthNames[month]+' '+year;

    const first = new Date(year,month,1);
    const startOffset = (first.getDay()+1)%7; // Saturday first
    const daysInMonth = new Date(year,month+1,0).getDate();
    const today = new Date();
    const isTodayMonth = today.getFullYear()===year && today.getMonth()===month;

    grid.innerHTML='';
    const cells=[];
    for(let i=0;i<startOffset;i++) cells.push('');
    for(let d=1;d<=daysInMonth;d++) cells.push(d);
    while(cells.length%7) cells.push('');

    cells.forEach((d,idx)=>{
      const cell=document.createElement('div');
      if(d===''){
        cell.className='cal-day empty';
        grid.appendChild(cell);
        return;
      }
      const btn=document.createElement('button');
      btn.className='cal-day';
      btn.textContent=d;
      btn.setAttribute('data-day',d);
      if(isTodayMonth && d===today.getDate()) btn.classList.add('today');
      if(state.day===d) btn.classList.add('selected');
      btn.addEventListener('click',()=>{
        state.day=d;
        renderMonth();
        updateSummary();
      });
      grid.appendChild(btn);
    });
  }

  function updateSummary(){
    if(state.day && state.time){
      const m = monthNames[state.month];
      summary.innerHTML = '<bdi dir="ltr">'+state.time+'</bdi> · '+state.day+' '+m;
      summary.classList.add('show');
      confirmBtn.textContent=' تأكيد الحجز — '+state.day+' '+monthNames[state.month]+'، '+state.time;
      confirmBtn.disabled=false;
      hint.textContent='سيتم تأكيد الحجز مع د. خالد العطية';
    } else {
      summary.classList.remove('show');
      confirmBtn.textContent=' تأكيد الحجز';
      confirmBtn.disabled=true;
      hint.textContent = state.day ? 'اختر الوقت المفضل' : 'اختر اليوم والوقت للمتابعة';
    }
  }

  // time slots
  const slots=['9:00','9:30','10:00','10:30','11:00','11:30','12:00'];
  const slotWrap = document.getElementById('slots');
  slots.forEach(s=>{
    const b=document.createElement('button');
    b.className='slot';
    b.innerHTML='<bdi dir="ltr">'+s+'</bdi>';
    b.addEventListener('click',()=>{
      state.time=s;
      slotWrap.querySelectorAll('.slot').forEach(x=>x.classList.remove('selected'));
      b.classList.add('selected');
      updateSummary();
    });
    slotWrap.appendChild(b);
  });

  document.getElementById('prevMonth').addEventListener('click',()=>{
    state.month--;
    if(state.month<0){state.month=11;state.year--;}
    state.day=null;
    renderMonth();updateSummary();
  });
  document.getElementById('nextMonth').addEventListener('click',()=>{
    state.month++;
    if(state.month>11){state.month=0;state.year++;}
    state.day=null;
    renderMonth();updateSummary();
  });

  confirmBtn.addEventListener('click',()=>{
    confirmBtn.textContent='...تم الحجز بنجاح';
    confirmBtn.disabled=true;
  });

  renderMonth();
  updateSummary();
})();
</script>
